-- C04 THAW — WRITES. Generated by build-and-verify.py; do not edit by hand.
-- Reverses 06 only for promos that nobody changed since they were frozen. One transaction.
-- If any frozen promo was written in any way since 06 (edited, retargeted, deleted, re-activated, or toggled on and
-- off again; detected by row version, fingerprint and targets), NOTHING is re-activated: the error lists them. Record the decision for each listed promo, then re-run:
--   update ops_c04.frozen_package_promos set thawed_at = now(), resolution = '<decision>' where promo_id = '<id>';
-- Re-activation still passes the C04 target guard and the checkout FIFO floor; sales are never touched.
begin;
set local lock_timeout = '5s';
set local timezone = 'UTC';
do $thaw$
declare drifted text;
begin
  if to_regprocedure('public.assert_active_package_promo_target()') is null
     or (select md5(prosrc) from pg_proc where oid = to_regprocedure('public.assert_active_package_promo_target()')) is distinct from '56845e957b2bdeac4e84d2e852623cf6'
     or (select count(*) from pg_trigger t where t.tgenabled = 'O' and t.tgfoid = to_regprocedure('public.assert_active_package_promo_target()')
         and ((t.tgname = 'promo_package_target_header_guard' and t.tgrelid = 'public.promos'::regclass)
           or (t.tgname = 'promo_package_target_items_guard' and t.tgrelid = 'public.promo_items'::regclass))) <> 2
     or not exists (select 1 from pg_constraint where conname = 'promos_discount_mode_valid' and conrelid = 'public.promos'::regclass) then
    raise exception 'C04_INSTALL_DRIFT: C04 objects differ from the tested build; stop and send this to the developer';
  end if;
  if to_regclass('ops_c04.frozen_package_promos') is null then
    raise exception 'C04_THAW_NOTHING_FROZEN';
  end if;
  lock table ops_c04.frozen_package_promos in share row exclusive mode;
  perform 1 from public.promos where id in (select promo_id from ops_c04.frozen_package_promos where thawed_at is null)
  order by id for update;
  select string_agg(f.promo_id::text, ', ' order by f.promo_id) into drifted
  from ops_c04.frozen_package_promos f left join public.promos p on p.id = f.promo_id
  where f.thawed_at is null
    and (p.id is null or p.is_active or p.xmin::text is distinct from f.row_version
         or md5((to_jsonb(p) - 'is_active')::text) is distinct from f.row_fingerprint
         or coalesce((select string_agg(i.item_id::text, ',' order by i.item_id) from public.promo_items i where i.promo_id = p.id), '') is distinct from f.targets);
  if drifted is not null then
    raise exception 'C04_THAW_DRIFT: changed since freeze, decide each one first: %', drifted;
  end if;
  update public.promos set is_active = true
  where id in (select promo_id from ops_c04.frozen_package_promos where thawed_at is null);
  update ops_c04.frozen_package_promos set thawed_at = now(), resolution = 'thawed unchanged' where thawed_at is null;
end $thaw$;
commit;
